<?php if(!defined('SW_APP')||!SW_PUBLIC){http_response_code(404);exit;} $rows=active_raffles(); ?>
<p class="user-sub">Hola, <?=h($u['first_names'])?>. Descubre los sorteos disponibles.</p><?php if(!$rows):?><div class="user-empty">No hay sorteos activos por el momento.</div><?php else:?><div class="user-raffles"><?php foreach($rows as $r):?><article><?php if($r['photo_slot']!==null):?><img src="<?=h(pub_photo_url($r))?>" alt="<?=h($r['title'])?>" loading="lazy"><?php endif;?><div><h2><?=h($r['title'])?></h2><p class="raffle-desc"><?=h($r['description'])?></p><strong><?=money($r['price_cents'])?> por boleto</strong></div></article><?php endforeach;?></div><?php endif;?><p class="user-sub">La selección de boletos y el pago en línea se habilitarán más adelante.</p>
